import {useCallback, type RefObject} from 'react'
import {requestSubmit} from '@github-ui/form-utils'

/**
 * Hook for handling quick-submit keyboard shortcuts (Cmd/Ctrl+Enter)
 * Replicates the behavior of js-quick-submit.ts for React components
 *
 * @param inputRef - Reference to the input element (can be null)
 * @returns handleKeyDown callback for use on input elements
 */
export function useQuickSubmitHandler(inputRef: RefObject<HTMLInputElement | null>) {
  return useCallback(
    (event: React.KeyboardEvent<HTMLInputElement>) => {
      // TODO: Refactor to use data-hotkey
      /* eslint eslint-comments/no-use: off */
      /* eslint-disable @github-ui/ui-commands/no-manual-shortcut-logic */
      if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') {
        const form = inputRef.current?.form
        if (form) {
          const button = form.querySelector('input[type=submit], button[type=submit]')
          if (event.shiftKey) {
            const altButton = form.querySelector('.js-quick-submit-alternative')
            if (
              (altButton instanceof HTMLInputElement || altButton instanceof HTMLButtonElement) &&
              !altButton.disabled
            ) {
              requestSubmit(form, altButton)
            }
          } else if (button instanceof HTMLInputElement || button instanceof HTMLButtonElement) {
            if (!button.disabled) {
              requestSubmit(form)
            }
          } else {
            requestSubmit(form)
          }
          event.preventDefault()
        }
      }
      /* eslint-enable @github-ui/ui-commands/no-manual-shortcut-logic */
    },
    [inputRef],
  )
}
